-- Réplica local con la forma real del HCM en PostgreSQL (SPEC-012 S1).
-- Adaptación de db/hcm-real/upstream.sql (entrada verbatim del usuario):
--   * datetime -> timestamp (literal), EXCEPTO time_check_date_utc ->
--     timestamptz porque el nombre declara instante UTC (la vista necesita
--     instantes con zona; decisión documentada).
--   * AUTO_INCREMENT -> INTEGER/BIGINT GENERATED BY DEFAULT AS IDENTITY
--     (permite al seed insertar ids deterministas).
--   * tinyint -> smallint, bit(1) -> boolean, mediumtext -> text,
--     float(10,6) -> double precision (los valores del seed llevan6 decimales).
--   * cláusulas CHARACTER SET/COLLATE no aplican en PostgreSQL.
--   * 'job:title' del paste (comillas simples = artefacto) se conserva como
--     nombre exacto de columna entrecomillado: "job:title" (SPEC-012 §10.2).
-- AÑADIDOS LOCALES (SPEC-012 §10.3, supuestos del DDL que no traía FKs):
--   * FK referenciales entre tablas; time_check.delay_id NO lleva FK porque
--     su valor por defecto0 es un centinela sin fila.
--   * Índices de apoyo en columnas de unión/rango (el DDL no traía índices).
-- Vocabulario de status del usuario (verbatim): 1 pendiente, 2 activo, 3 eliminado.

CREATE TABLE public.employee (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_on timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_on timestamp NULL,
    first_email varchar(75) NOT NULL DEFAULT '',
    phone varchar(20) NOT NULL DEFAULT '',
    birthday_date timestamp NULL,
    hire_date timestamp NULL,
    name varchar(75),
    department varchar(75),
    last_name varchar(75) DEFAULT '',
    -- Añadido local del dataset ficticio (2026-10-25): el shape real pegado no
    -- expone género y el usuario pidió contar hombres/mujeres. No se usa para
    -- inferir nada; el contrato lo sirve como valor de la fuente.
    gender varchar(1) NULL,
    last_login timestamp NULL,
    language_id integer NULL,
    role_id integer NOT NULL DEFAULT 0,
    status_id smallint NOT NULL DEFAULT 2,
    "job:title" varchar(75),
    updated_on timestamp NULL,
    vacancy_supervisor integer NOT NULL DEFAULT 0,
    timecheck_supervisor integer NOT NULL DEFAULT 0,
    photo_url varchar(250) NULL,
    second_email varchar(75) NOT NULL DEFAULT ''
);

CREATE TABLE public.timeoff_type (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    amount integer NOT NULL DEFAULT 0,
    date_start timestamp NULL,
    date_end timestamp NULL,
    name varchar(100),
    status_id smallint NOT NULL DEFAULT 1,
    fiscal_year integer NOT NULL DEFAULT 0,
    created_on timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE public.timeoff (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    date_start timestamp NOT NULL,
    date_end timestamp NULL,
    note varchar(1000),
    status_id smallint NOT NULL DEFAULT 1,
    timeoff_type_id integer NOT NULL,
    employee_id integer NOT NULL,
    employee_id_supervisor integer NULL,
    date_supervised timestamp NULL,
    supervisor_note text NULL,
    fiscal_year integer NULL,
    by_hour boolean NOT NULL DEFAULT false,
    created_on timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_timeoff_type FOREIGN KEY (timeoff_type_id)
        REFERENCES public.timeoff_type (id),
    CONSTRAINT fk_timeoff_employee FOREIGN KEY (employee_id)
        REFERENCES public.employee (id),
    CONSTRAINT fk_timeoff_supervisor FOREIGN KEY (employee_id_supervisor)
        REFERENCES public.employee (id)
);

CREATE TABLE public.working_day (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    status_id integer NOT NULL,
    name varchar(50),
    description varchar(200),
    created_on timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    modified_on timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    enable_delays smallint DEFAULT 0,
    web_allowed boolean NOT NULL DEFAULT true,
    mobile_allowed boolean NOT NULL DEFAULT true,
    is_default boolean NOT NULL DEFAULT false
);

CREATE TABLE public.working_day_assigment (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    employee_id integer NOT NULL,
    working_day_id bigint NOT NULL,
    status_id integer NOT NULL,
    created_on timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    modified_on timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_assignment_employee FOREIGN KEY (employee_id)
        REFERENCES public.employee (id),
    CONSTRAINT fk_assignment_working_day FOREIGN KEY (working_day_id)
        REFERENCES public.working_day (id)
);

CREATE TABLE public.time_check_delay (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    comments varchar(1000) NULL,
    status_id smallint NOT NULL,
    created_on timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    modified_on timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    approved_by integer NOT NULL,
    employee_id integer NOT NULL,
    CONSTRAINT fk_delay_employee FOREIGN KEY (employee_id)
        REFERENCES public.employee (id),
    CONSTRAINT fk_delay_approver FOREIGN KEY (approved_by)
        REFERENCES public.employee (id)
);

-- Orden de creación: time_check después de time_check_delay porque su
-- delay_id centinela0 queda sin FK; working_day y employee ya existen.
CREATE TABLE public.time_check (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    employee_id integer NOT NULL,
    working_day_id bigint NOT NULL,
    check_type_id smallint NOT NULL,
    checkout_type_id integer NOT NULL,
    time_check_date_utc timestamptz NOT NULL,
    time_check_date_long bigint NOT NULL,
    time_check_timezone varchar(64) NULL,
    check_device_type_id smallint NOT NULL,
    status_id smallint NOT NULL,
    supervisor_status_date timestamp NOT NULL,
    employee_note varchar(1000) NULL,
    longitude double precision NOT NULL,
    latitude double precision NOT NULL,
    ip_address varchar(50) NOT NULL,
    created_on timestamp NOT NULL,
    modified_on timestamp NOT NULL,
    delay_id integer NOT NULL DEFAULT 0,
    photo_face_url varchar(255) NULL,
    photo_face_status_id smallint DEFAULT 0,
    CONSTRAINT fk_timecheck_employee FOREIGN KEY (employee_id)
        REFERENCES public.employee (id),
    CONSTRAINT fk_timecheck_working_day FOREIGN KEY (working_day_id)
        REFERENCES public.working_day (id)
);

-- Índices locales de apoyo (supuesto §10.3): el DDL de entrada no incluía índices.
CREATE INDEX idx_timecheck_employee_date ON public.time_check (employee_id, time_check_date_utc);
CREATE INDEX idx_timecheck_date ON public.time_check (time_check_date_utc);
CREATE INDEX idx_timeoff_employee_date ON public.timeoff (employee_id, date_start);
CREATE INDEX idx_assignment_employee ON public.working_day_assigment (employee_id);
CREATE INDEX idx_employee_department ON public.employee (department);
